<?php get_header(); ?><main class="container section"><h1 class="section-title">酒店店家</h1><div class="store-grid"><?php if(have_posts()):while(have_posts()):the_post(); $thumb_id=get_post_thumbnail_id(); ?><article class="store-card"><a href="<?php the_permalink(); ?>"><div class="store-card-image"><?php if($thumb_id)echo wp_get_attachment_image($thumb_id,'large',false,array('loading'=>'lazy','decoding'=>'async')); ?></div><div class="store-card-body"><h3><?php the_title(); ?></h3><?php $address=bsktv_meta('bsktv_address');if($address): ?><div class="store-meta"><?php echo esc_html($address); ?></div><?php endif; ?></div></a></article><?php endwhile;else:?><div class="empty">目前沒有店家資料。</div><?php endif;?></div></main><?php get_footer(); ?>